package com.taylordproductivty.med_timing_tracker.ui.components

import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.padding
import androidx.compose.material3.ExperimentalMaterial3Api
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Text
import androidx.compose.material3.TimeInput
import androidx.compose.material3.rememberTimePickerState
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.res.stringResource
import androidx.compose.ui.unit.dp
import com.taylordproductivty.med_timing_tracker.R
import java.util.Calendar

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun TimeTakenField(
    initialEpochMillis: Long,
    onEpochMillisChange: (Long) -> Unit,
    modifier: Modifier = Modifier,
) {
    val initialCalendar = remember(initialEpochMillis) {
        Calendar.getInstance().apply { timeInMillis = initialEpochMillis }
    }
    val timePickerState = rememberTimePickerState(
        initialHour = initialCalendar.get(Calendar.HOUR_OF_DAY),
        initialMinute = initialCalendar.get(Calendar.MINUTE),
        is24Hour = false,
    )
    LaunchedEffect(timePickerState.hour, timePickerState.minute) {
        val calendar = Calendar.getInstance().apply {
            timeInMillis = initialEpochMillis
            set(Calendar.HOUR_OF_DAY, timePickerState.hour)
            set(Calendar.MINUTE, timePickerState.minute)
            set(Calendar.SECOND, 0)
            set(Calendar.MILLISECOND, 0)
        }
        onEpochMillisChange(calendar.timeInMillis)
    }
    Column(modifier = modifier) {
        Text(stringResource(R.string.time_taken_label), style = MaterialTheme.typography.labelLarge)
        TimeInput(state = timePickerState, modifier = Modifier.padding(top = 4.dp))
    }
}
